module sequence_detector(
    input clk, 
    input reset_n, 
    input data_in,
    output sequence_detected
);
// Define states
parameter IDLE = 3'b000;
parameter S1 = 3'b001;
parameter S2 = 3'b010;
parameter S3 = 3'b011;
parameter S4 = 3'b100;
// Internal signals
reg [2:0] current_state, next_state;
// Next state logic
always @(posedge clk or negedge reset_n) begin
    if (~reset_n)
        current_state <= IDLE;
    else
        current_state <= next_state;
end
// State transitions logic
always @(*) begin
    case(current_state)
        IDLE: begin
            if (data_in == 1'b1)
                next_state = S1;
            else
                next_state = IDLE;
        end

        S1: begin
            if (data_in == 1'b0)
                next_state = S2;
            else
                next_state = IDLE;
        end

        S2: begin
            if (data_in == 1'b0)
                next_state = S3;
            else
                next_state = IDLE;
        end

        S3: begin
            if (data_in == 1'b1)
                next_state = S4;
            else
                next_state = IDLE;
        end

        S4: begin
            if (data_in == 1'b1)
                next_state = S1;
            else
                next_state = IDLE;
        end

        default: next_state = IDLE;
    endcase
end
// Output logic
assign sequence_detected = (current_state == S4);
endmodule
